import{_ as t,H as i,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const D=JSON.parse('{"title":"06 | 领域建模实践（下）：领域建模还有什么其他技巧？","description":"","frontmatter":{},"headers":[{"level":2,"title":"深入理解“多对多”关联","slug":"深入理解-多对多-关联","link":"#深入理解-多对多-关联","children":[{"level":3,"title":"处理“客户”","slug":"处理-客户","link":"#处理-客户","children":[]},{"level":3,"title":"处理“合同”","slug":"处理-合同","link":"#处理-合同","children":[]},{"level":3,"title":"处理“项目”","slug":"处理-项目","link":"#处理-项目","children":[]},{"level":3,"title":"处理“为项目分配员工”","slug":"处理-为项目分配员工","link":"#处理-为项目分配员工","children":[]},{"level":3,"title":"处理“登记工时”","slug":"处理-登记工时","link":"#处理-登记工时","children":[]}]},{"level":2,"title":"识别“操作”","slug":"识别-操作","link":"#识别-操作","children":[]},{"level":2,"title":"划分模块","slug":"划分模块","link":"#划分模块","children":[]},{"level":2,"title":"完善业务规则","slug":"完善业务规则","link":"#完善业务规则","children":[]},{"level":2,"title":"建立词汇表","slug":"建立词汇表","link":"#建立词汇表","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"手把手教你落地DDD/06｜领域建模实践（下）：领域建模还有什么其他技巧？.md","filePath":"手把手教你落地DDD/06｜领域建模实践（下）：领域建模还有什么其他技巧？.md","lastUpdated":1795557830000}'),s={name:"手把手教你落地DDD/06｜领域建模实践（下）：领域建模还有什么其他技巧？.md"};function p(r,e,l,o,E,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_06-领域建模实践-下-领域建模还有什么其他技巧" tabindex="-1">06 | 领域建模实践（下）：领域建模还有什么其他技巧？ <a class="header-anchor" href="#_06-领域建模实践-下-领域建模还有什么其他技巧" aria-label="Permalink to &quot;06 | 领域建模实践（下）：领域建模还有什么其他技巧？&quot;">​</a></h1><p>你好，我是钟敬。</p><p>上节课咱们介绍了领域建模的一些概念，也一起完成了有关租户、组织和员工的领域建模。今天这一讲，我们继续对项目管理、人员分配和工时登记部分进行建模。</p><p>在完成领域模型的过程中，我们还会对“多对多关联”进行更深入的学习，一起识别“操作”，并且划分模块，最后还会完善业务规则并建立词汇表。掌握了这些技巧，你就可以尝试运用领域建模解决一些实际问题了。</p><h2 id="深入理解-多对多-关联" tabindex="-1">深入理解“多对多”关联 <a class="header-anchor" href="#深入理解-多对多-关联" aria-label="Permalink to &quot;深入理解“多对多”关联&quot;">​</a></h2><p>和上节课一样，我们从项目管理部分的领域名词开始建模。同样，你是架构师，我是产品经理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/1.png" alt=""></a></p><p>我们先假定每个名词都是一个实体，然后再把这些实体一个个加到已有的模型图里。初步识别出的实体有下面这些：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/2.png" alt=""></a></p><h3 id="处理-客户" tabindex="-1">处理“客户” <a class="header-anchor" href="#处理-客户" aria-label="Permalink to &quot;处理“客户”&quot;">​</a></h3><p>我们首先来处理客户实体。按照需求，每个客户有一个客户经理负责。你和我确认了一下：“客户经理也是员工对吧？”我说：“是的。”于是你把客户添加到了模型里，如下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/3.png" alt=""></a></p><p>这里你把客户经理当作了一个角色，员工和客户的关联翻译成自然语言就是“一个员工可以充当多个客户的客户经理，而一个客户有且仅有一个员工作为他的客户经理”。</p><h3 id="处理-合同" tabindex="-1">处理“合同” <a class="header-anchor" href="#处理-合同" aria-label="Permalink to &quot;处理“合同”&quot;">​</a></h3><p>完成了对客户的建模，我们开始处理合同实体。根据需求，“每个合同都有一个销售人员负责”，于是，你画出了下面的模型图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/4.png" alt=""></a></p><p>你有些疑惑：“客户经理是不是也是销售人员呢？”我说：“是的。”于是你意识到：“销售人员应该也是员工的一种岗位，并且在与客户的关联中，充当了客户经理这个角色。那么，类似地，销售人员又充当合同的什么角色呢？”我说：“就叫合同经理吧。”</p><p>于是，你修改了销售人员这个角色的名字，并且在岗位的注释中增加了销售人员。此外，你又增加了“只有销售人员才能作客户经理” 以及“只有销售人员才能作合同经理”这两条业务规则。</p><p>现在的模型图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/5.png" alt=""></a></p><h3 id="处理-项目" tabindex="-1">处理“项目” <a class="header-anchor" href="#处理-项目" aria-label="Permalink to &quot;处理“项目”&quot;">​</a></h3><p>接着，你又用类似的方法，增加了项目实体：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/6.png" alt=""></a></p><h3 id="处理-为项目分配员工" tabindex="-1">处理“为项目分配员工” <a class="header-anchor" href="#处理-为项目分配员工" aria-label="Permalink to &quot;处理“为项目分配员工”&quot;">​</a></h3><p>现在我们考虑“为项目分配员工”和“员工退出项目”这两个需求。</p><p>首先，我在图里面的员工和项目之间增加了一个表示“员工被分配到项目上”的关联，同时把“一个员工预计的投入百分比不能大于百分之百”的规则也标注出来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/7.png" alt=""></a></p><p>这时候，员工和项目之间就有了两个不同的关联。原来那个一对多关联表达的是“员工充当项目经理”的关系。</p><p>另外，我们新增了一个关联，表示分配员工的关系。一个员工可以被分配到多个项目上，一个项目上又可以有多个员工，因此两者是“多对多”关联。在这个关联的员工一端，写上了项目成员这个角色。也就是员工充当了项目的项目成员。</p><p>在这里我们可以看到，两个实体之间，可以有多个关联。不同的关联代表不同含义，数量关系也可以不同，可以用角色名来区分。</p><p>然后你问我：“这里有一个关于投入百分比的规则，那么投入百分比这个属性应该记录在哪个实体上呢？”这时候我们发现了一个尴尬的问题，这个百分比既不能记录在员工实体上，也不能记录在项目实体上。</p><p>这是因为，只有员工和项目建立了项目成员这一关联的时候，记录投入百分比才是有意义的，也就是说，这个属性应该记录在这个多对多关联上。那么这在 UML 中怎么表达呢？</p><p>于是，我把模型改成了下面的样子：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/8.png" alt=""></a></p><p>这时候，原来的项目成员角色演变成了一个独立的实体，来表达员工和项目之间的多对多关联。预计投入百分比也就自然放在这个实体里面了。</p><p>注意，这时候，员工和项目成员之间的关联是一对多，项目和项目成员之间也是一对多。然后我总结道：“任何多对多关联，总能用类似的方法，通过引入一个表示关联的实体，拆成两个一对多的关联。”</p><p>接着，你又注意到一个问题，一个员工可以分配到一个项目上，然后退出项目，然后再一次分配到这个项目上，所以，我们就应该用时间段来记录员工参与项目的历史。</p><p>考虑到时间因素，有关投入百分比的业务规则可以进一步明确为“在任何时刻，一个人的预计投入百分比总和不能大于百分之百。”此外，从逻辑上，还可以识别一条规则一个员工在同一个项目上的时间段不能重叠。</p><p>于是你这样改进了模型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/9.png" alt=""></a></p><h3 id="处理-登记工时" tabindex="-1">处理“登记工时” <a class="header-anchor" href="#处理-登记工时" aria-label="Permalink to &quot;处理“登记工时”&quot;">​</a></h3><p>接下来，为了处理报工时的需求，你又增加了工时记录实体，以及相关的业务规则：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/10.png" alt=""></a></p><p>同样，我们可以把工时记录看作员工和项目之间的一种多对多关系。</p><h2 id="识别-操作" tabindex="-1">识别“操作” <a class="header-anchor" href="#识别-操作" aria-label="Permalink to &quot;识别“操作”&quot;">​</a></h2><p>经过上面的梳理，我们已经把剩余的模型梳理得差不多了。但是，在事件风暴中咱们还遗留了一个问题：怎么处理客户经理上级、销售人员上级和项目经理上级这几个概念？现在看来，它们不太像是独立的实体，而更像是某种关系。</p><p>经过讨论我们发现，客户经理、销售人员、项目经理，无非都是员工，所以他们的上级，其实都可以归纳为取员工上级这个操作。然后我们讨论出了取员工上级的逻辑：</p><p>第一，如果员工不是所属组织的负责人，那么这个组织的负责人就是员工的上级；</p><p>第二，如果员工就是所属组织的负责人，那么这个组织的上级组织的负责人就是这个员工的上级。</p><p>你看，在上述逻辑中，我们又引入了一个组织负责人的概念。可以认为，负责人是员工在与组织的关联中充当的一种角色。</p><p>基于这些理解，我把模型进一步完善了一下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/11.png" alt=""></a></p><p>在这个模型中，有几个要注意的地方：</p><p>第一，为了表达组织的负责人，我在员工和组织之间又增加了一个一对多关联，表示“一个员工可以不作任何组织的负责人，也可以作多个组织的负责人；而一个组织可以暂时没有负责人，但最多只能有一个负责人。”</p><p>现在，组织和员工之间就有两种不同的关联了，分别用了成员和负责人两种角色来区分。</p><p>第二，我们在员工实体上增加了取上级这个操作。操作（operation）在 UML 里也叫方法（method）。对象的属性是静态的值，而操作是动态的逻辑。在 UML 中，操作用“操作名 + 括号”的方式表示，括号中可以写参数。</p><p>第三，我们用一个注解说明了取上级这个操作的业务逻辑。</p><p>现在，我们的领域模型已经覆盖了事件风暴中发现的所有领域概念，但是，你是不是觉得这个图已经有点乱，不太容易理解了呢？</p><h2 id="划分模块" tabindex="-1">划分模块 <a class="header-anchor" href="#划分模块" aria-label="Permalink to &quot;划分模块&quot;">​</a></h2><p>之所以这个图不容易理解，是因为很多实体和关联混杂在一起，形成了一个“蜘蛛网”。但人的认知能力是有限的，面对这样一张复杂的对象网络，就产生了认知过载（cognitiveoverload）。</p><p>解决这一问题的方法就是“模块化”。也就是说，把模型中的业务概念组织成若干高内聚的模块（module），而模块之间尽量低耦合。</p><p>在 UML 中，可以用包来表示模块。包的符号是下面这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/12.png" alt=""></a></p><p>包的内部可以包含实体，也可以包含另外的包。在 UML 中，任何需要对元素进行分组的场合，都可以使用包。经过一番讨论，我们采用如下方式划分模块：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/13.png" alt=""></a></p><p>也就是说，我们把模型分成了 4 个模块，分别是租户管理、组织管理、项目管理和工时管理。是不是感觉清晰多了？</p><p>有了模块，我们就可以从两个层面理解模型。</p><p>第一个是宏观层面。宏观层面只关心模型中有哪些模块，以及模块间的依赖关系，不关心模块内部的细节。为了达到这个目的，我们可以画出更宏观的包图。像下面这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/14.png" alt=""></a></p><p>这里我们又引入了一个新的符号，就是带箭头的虚线。这在 UML 中表示依赖（dependency）关系，箭头由依赖方指向被依赖方。</p><p>从图中我们看到：</p><p>首先，所有模块都依赖租户管理。这是因为，为了将不同租户的数据区别开来，每个模块中的实体都要说明自己是哪个租户的；</p><p>其次，项目管理依赖组织管理。这是因为项目经理、项目成员等概念都依赖于组织管理中的员工；</p><p>还有，工时管理既依赖组织管理又依赖项目管理。这是因为工时管理要说明（组织管理中的）哪个员工在（项目管理中的）哪个项目上投入了多少工时。</p><p>我们要注意，依赖关系和前面讲的关联关系是不一样的。关联表示的是数据上的导航关系。例如，当我们说组织和员工之间具有一对多关联的时候，就意味着，由组织可以找到下面的员工，由员工也可以找到所属的组织。</p><p>依赖表示的意思更为广泛。如果 A、B 两个元素，有了 A 才能有 B，那么就可以说 B 依赖于A。</p><p>我们可以认为关联是一种特殊的依赖关系，但依赖还有别的形式，比如说项目管理模块依赖于组织管理模块，两者之间未必有直接的数据导航关系，可能只是项目管理调用组织管理，获得需要的数据。</p><p>理解模型的第二个层面是微观层面，也就是深入到模块内部，了解实体和关联等等的细节。</p><p>通过这种分而治之的方法，我们可以在一定程度上管理复杂性，解决认知过载的问题。如果模型更加复杂，那么还要进一步采用限界上下文来处理，这个会在第三个迭代再介绍。</p><p>现在，领域模型基本完成了。为了完善开发过程，我们还要再进行两个实践：一个是完善业务规则，另一个是建立词汇表。</p><h2 id="完善业务规则" tabindex="-1">完善业务规则 <a class="header-anchor" href="#完善业务规则" aria-label="Permalink to &quot;完善业务规则&quot;">​</a></h2><p>我们在做事件风暴时就开始识别业务规则了，在领域建模中又识别出了更多的规则，所以现在我们需要把这些规则补充到业务规则表之中，如下表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/15.png" alt=""></a></p><p>其中，从 R006 开始，是我们领域建模阶段新识别出的领域规则。</p><h2 id="建立词汇表" tabindex="-1">建立词汇表 <a class="header-anchor" href="#建立词汇表" aria-label="Permalink to &quot;建立词汇表&quot;">​</a></h2><p>接着我们来建立词汇表，也就是把事件风暴和领域模型中重要的词汇列成表。为什么要建立词汇表呢？主要是有两个作用。</p><p>首先，我们需要通过词汇表来规范领域模型中的词汇。同一个词，可能会在领域模型中出现多次，时间久了，就可能不一致，因此需要进一步规范。</p><p>第二，是可以用于后续编程中的命名。按照 DDD 的要求，程序中的各种命名也需要统一，并且需要与领域模型中保持一致。我们会在词汇表中列出英文全称和缩写，以达到这个目的。</p><p>词汇表是保证统一语言的重要手段。</p><p>目前为止的重要词汇，都列到下面这张词汇表里了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/06/16.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>好，这节课的主要内容就讲完了，下面来总结一下。</p><p>今天我们在上节课的基础上，继续对项目管理和工时管理进行领域建模。在这个过程中进一步深化了对“多对多”关联的理解：我们可以通过引入一个表示关联的实体，将一个多对多关联拆成两个一对多关联。</p><p>我们还通过取员工上级的逻辑，学习了为实体添加操作。当模型变得比较复杂时，可以把模型划分成多个模块，使模型更容易理解。</p><p>在建立完领域模型之后，我们还进行了两项实践：完善业务规则和建立词汇表。很多朋友过去并不重视这两个实践，然而，它们对落实 DDD 实践，具有很重要的作用，一定要引起重视。</p><p>最后还要强调一点，领域建模易学难精，需要不断地练习才能熟练掌握。希望你能拿自己的实际项目练习一下。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>今天我们讲过，一个多对多关联可以拆成两个一对多关联，那么你觉得什么时候应该拆，什么时候不拆呢？</p></li><li><p>客户经理是可以更换的，如果要保留更换历史，模型图应该怎样改呢？</p></li></ol><p>好，今天的课程结束了，有什么问题欢迎在评论区留言。下节课，我们再从理论上深入理解一下“什么是模型”以及“什么是模型驱动设计”。</p>',100)])])}const B=t(s,[["render",p]]);export{D as __pageData,B as default};
